function linearCounts(a, x) {
  if (!Array.isArray(a) || !Array.from(a).every(Number.isSafeInteger)) {
    throw new TypeError("Use a dense array of safe integers");
  }
  if (!Number.isSafeInteger(x)) throw new TypeError("Use an integer target");
  let i = 0, keys = 0, bounds = 0;
  while (true) {
    bounds++;
    if (i >= a.length) break;
    keys++;
    if (a[i] === x) break;
    i++;
  }
  bounds++;
  const position = i < a.length ? i + 1 : 0;
  return {position, keys, bounds, total: keys + bounds};
}

function closestPair(points) {
  if (!Array.isArray(points) || points.length < 2) {
    throw new TypeError("Use at least two points");
  }
  const p = Array.from(points, v => {
    if (!Array.isArray(v) || v.length !== 2 ||
        !Array.from(v).every(x => Number.isSafeInteger(x) && Math.abs(x) <= 1000000)) {
      throw new TypeError("Use integer coordinate pairs with magnitude at most 1000000");
    }
    return v.slice();
  });
  let best = Infinity, pair = null, pairs = 0;
  for (let i = 0; i < p.length; i++) {
    for (let j = i + 1; j < p.length; j++) {
      const dx = p[j][0] - p[i][0];
      const dy = p[j][1] - p[i][1];
      const squared = dx * dx + dy * dy;
      pairs++;
      if (squared < best) { best = squared; pair = [i, j]; }
    }
  }
  return {pair, squaredDistance: best, pairs};
}
